export interface SecretShape {
  /** What the shape is. */
  readonly name: string;
  /** The pattern, in the dialect Python and JavaScript read alike. */
  readonly source: string;
  /** The flags for `new RegExp`: `g`, and `i` when the shape ignores case. */
  readonly flags: string;
  /** Whether group 1 stays as it was and only what follows it is replaced. */
  readonly keepHead: boolean;
}

/** One line of text and what masking it leaves: what both sides are held to. */
export interface SecretShapeCase {
  readonly name: string;
  readonly text: string;
  /** The same text when nothing in it is a secret. */
  readonly masked: string;
}

